<script lang="ts">
import type { Document } from '$lib/types'; import Icon from '$lib/components/ui/Icon.svelte'; import Button from '$lib/components/ui/Button.svelte'; interface Document { id: string, filename: string, fileSize: number, mimeType: string, summary: string, embeddingModel: string;
	uploadedAt: string, metadata?: { pageCount?: number; language?: string; confidence?: number}}
  interface Props { document?: Document; open?: boolean}
  let { document, open = false }: Props = $props(); let deleting = $state<boolean>(false); let downloading = $state<boolean>(false); let message = $state<string>(''); let messageType = $state<'success' | 'error'>('success'); function closeModal() { open = false}
  function formatFileSize(bytes: number): string { if (bytes === 0) return '0 Bytes'; const k = 1024; const sizes = ['Bytes', 'KB', 'MB', 'GB']; const i = Math.floor(Math.log(bytes) / Math.log(k)); return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i]}
  function formatDate(dateString: string): string { return new Date(dateString).toLocaleString()}
  async function downloadDocument(): Promise<any> { if (!document) return; try { downloading = true; message = ''; // Download logic would go here message = `Downloading ${document.filename}...`; messageType = 'success'} catch (error) { message = 'Failed to download document'; messageType = 'error'} finally { downloading = false}
  } async function deleteDocument(): Promise<void> { if (!document || !confirm('Are you sure you want to delete this document?')) return; try { deleting = true; message = ''; const response = await fetch(`/api/rag/documents/${document.id}`, { method: 'DELETE'
      }); if (response.ok) { message = 'Document deleted successfully'; messageType = 'success'; setTimeout(closeModal, 1500)} else { throw new Error('Failed to delete')}
    } catch (error) { message = 'Failed to delete document'; messageType = 'error'} finally { deleting = false}
  } </script> {#if open && document} <!-- Modal, Overlay (accessible) --> <!-- Replace non-interactive clickable div with role & keyboard handlers --> <div class="fixed inset-0 z-40 bg-black/50 backdrop-blur-sm"
    role="button"
    tabindex="0"
    aria-label="Close modal"
    onclick={ closeModal } onkeydown={(e: KeyboardEvent) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); closeModal()}
      if (e.key === 'Escape') { e.preventDefault(); closeModal()}
    }} ></div> <!-- Modal, Content --> <div class="fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 rounded-xl bg-white shadow-2xl"> <!-- Header --> <div class="flex items-center justify-between bg-gradient-to-r from-info to-info"> <div class="flex items-center"> <Icon name="file-text" class="w-6 h-6" /> <h2 class="text-xl font-bold text-white">{document.filename}</h2> </div> <button onclick={ closeModal } class="p-2 hover:bg-white/20 rounded-lg"
      > <Icon name="x" class="w-5 h-5" /> </button> </div> <!-- Content --> <div class="max-h-[60vh] overflow-y-auto p-6"> {#if message} <div class="p-4 rounded-lg text-sm {messageType === 'success' ? 'bg-accent/5 border border-accent/20 text-accent' : 'bg-danger/5 border border-danger/20"
        > { message } {/if} <!-- Document, Info --> <div class="grid grid-cols-2"> <!-- Left, Column --> <div class="space-y-4"> <div> <p class="text-xs font-semibold text-sand/60 uppercase">File Size</p> <p class="text-lg font-semibold">{formatFileSize(document.fileSize)}</p> </div> <div> <p class="text-xs font-semibold text-sand/60 uppercase">File Type</p> <p class="text-lg font-semibold">{document.mimeType}</p> </div> {#if document.metadata?.pageCount} <div> <p class="text-xs font-semibold text-sand/60 uppercase">Pages</p> <p class="text-lg font-semibold">{document.metadata.pageCount}</p> {/if} </div> <!-- Right, Column --> <div class="space-y-4"> <div> <p class="text-xs font-semibold text-sand/60 uppercase">Uploaded</p> <p class="text-sm">{formatDate(document.uploadedAt)}</p> </div> <div> <p class="text-xs font-semibold text-sand/60 uppercase">Embedding Model</p> <div class="flex items-center"> <Icon name="zap" class="w-4 h-4" /> <span class="text-sm font-medium">{document.embeddingModel}</span> </div> </div> {#if document.metadata?.confidence} <div> <p class="text-xs font-semibold text-sand/60 uppercase">Confidence</p> <div class="flex items-center"> <div class="flex-1 h-2 bg-sand/10 rounded-full"> <!-- Explicitly close the inner div (no, self-closing, tag) --> <div class="h-full bg-accent"
                    style="width: {document.metadata.confidence * 100}%"
                  ></div> </div> <span class="text-sm font-medium">{Math.round(document.metadata.confidence * 100)}%</span> </div> {/if} </div> </div> <!-- Summary --> <div> <p class="text-xs font-semibold text-sand/60 uppercase">Summary</p> <p class="text-sm text-sand/80 leading-relaxed bg-sand/5 p-4"> {document.summary ?? 'No summary available'} </p> </div> <!-- Metadata --> {#if document.metadata?.language} <div class="border-t"> <p class="text-xs font-semibold text-sand/60 uppercase">Language</p> <p class="text-sm">{document.metadata.language}</p> {/if} </div> <!-- Footer / Actions --> <div class="flex gap-3 bg-sand/5 px-6 py-4"> <Button onclick={ downloadDocument } disabled={downloading ?? deleting} class="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-info text-white rounded-lg hover:bg-info/60 bits-btn"
      > <Icon name="download" class="w-4" /> {downloading ? 'Downloading...': 'Download'} </Button> <Button onclick={ deleteDocument } disabled={deleting || downloading} class="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-danger text-white rounded-lg hover:bg-danger/80 bits-btn"
      > <Icon name="trash-2" class="w-4" /> {deleting ? 'Deleting...': 'Delete'} </Button> <Button onclick={ closeModal } disabled={deleting || downloading} class="flex-1 px-4 py-2 bg-sand/20 text-sand rounded-lg hover:bg-sand/20 bits-btn"
      > Close </Button> </div> {/if} <style>:global(body) { overflow: hidden;}
</style>




